+/* Write out a tree's data, and any child nodes, as WSML */
+static void
+proto_tree_write_node_wsml(proto_node* node, gpointer data)
+{
+    ws_assert(node);
+    ws_assert(node->finfo);
+    ws_assert(data);
+
+    write_wsml_data* node_callback_data = (write_wsml_data*)data;
+
+    const char* name = node->finfo->hfinfo->abbrev;
+    const char* display_name = node->finfo->hfinfo->name;
+    const char* type = ftype_name(node->finfo->hfinfo->type);
+
+    tvbuff_t* current_buffer = node->finfo->ds_tvb;
+    gint32 buffer_index = -1;
+
+    // If there is a buffer get its id
+    if (current_buffer != NULL)
+    {
+        // Was this buffer seen before?
+        gint32 current_buffer_index = 0;
+        GSList* data_sources_item = node_callback_data->data_sources;
+        while (data_sources_item != NULL)
+        {
+            struct data_source* data_source = (struct data_source*)data_sources_item->data;
+            tvbuff_t* buffer = get_data_source_tvb(data_source);
+            if (current_buffer == buffer)
+            {
+                buffer_index = current_buffer_index;
+                break;
+            }
+            current_buffer_index++;
+            data_sources_item = data_sources_item->next;
+        }
+    }
+
+    char* value = fvalue_to_string_repr(NULL, &(node->finfo->value), FTREPR_DISPLAY, node->finfo->hfinfo->display);
+
+    const char* representation = node->finfo->rep->representation != NULL ? node->finfo->rep->representation : "";
+
+    gboolean write_field = TRUE;
+    // If no specific list of output fields is given this field will be written
+    // If a specific list of output fields is given we need to find out if this field is contained in that list. If yes, it will be written.
+    if (node_callback_data->fields != NULL && node_callback_data->fields->fields != NULL)
+    {
+        write_field = FALSE;
+        for (guint i = 0; i < node_callback_data->fields->fields->len; i++)
+        {
+            gchar* field_name = (gchar*)g_ptr_array_index(node_callback_data->fields->fields, i);
+            if (g_strcmp0(field_name, name) == 0)
+            {
+                write_field = TRUE;
+                break;
+            }
+        }
+    }
+
+    if (write_field == TRUE)
+    {
+        fprintf(node_callback_data->fh, "\n");
+        print_indent(node_callback_data->level_of_indentation, node_callback_data->fh);
+        fprintf(node_callback_data->fh, "<field");
+
+        fprintf(node_callback_data->fh, " name=\"%s\"", name);
+        fprintf(node_callback_data->fh, " display_name=\"");
+        print_escaped_xml(node_callback_data->fh, display_name);
+        fprintf(node_callback_data->fh, "\"");
+        fprintf(node_callback_data->fh, " type=\"%s\"", type);
+
+        fprintf(node_callback_data->fh, " value=\"");
+        if (value != NULL)
+        {
+            print_escaped_xml(node_callback_data->fh, value);
+            wmem_free(NULL, value);
+        }
+        fprintf(node_callback_data->fh, "\"");
+
+        fprintf(node_callback_data->fh, " start_position=\"%d\"", node->finfo->start);
+        fprintf(node_callback_data->fh, " length=\"%d\"", node->finfo->length);
+        fprintf(node_callback_data->fh, " buffer_index=\"%d\"", buffer_index);
+        fprintf(node_callback_data->fh, " hidden=\"%s\"", (node->finfo->flags & FI_HIDDEN) != 0 ? "true" : "false");
+        fprintf(node_callback_data->fh, " generated=\"%s\"", (node->finfo->flags & FI_GENERATED) != 0 ? "true" : "false");
+        fprintf(node_callback_data->fh, " big_endian=\"%s\"", (node->finfo->flags & FI_BIG_ENDIAN) != 0 ? "true" : "false");
+        fprintf(node_callback_data->fh, " representation=\"");
+        print_escaped_xml(node_callback_data->fh, representation);
+
+
+        // Only add a linebreak if the node has at least one child
+        if (node->first_child != NULL)
+        {
+            fprintf(node_callback_data->fh, "\">");
+        }
+        else
+        {
+            fprintf(node_callback_data->fh, "\"");
+        }
+    }
+
+    // Process the children recursively
+    node_callback_data->level_of_indentation++;
+    proto_tree_children_foreach(node, proto_tree_write_node_wsml, node_callback_data);
+    node_callback_data->level_of_indentation--;
+
+    if (write_field == TRUE)
+    {
+        // Only add a linebreak if the node has at least on child
+        if (node->first_child != NULL)
+        {
+            fprintf(node_callback_data->fh, "\n");
+            print_indent(node_callback_data->level_of_indentation, node_callback_data->fh);
+            fprintf(node_callback_data->fh, "</field>");
+        }
+        else
+        {
+            fprintf(node_callback_data->fh, "/>");
+        }
+    }
+}
