+void
+write_wsml_proto_tree(output_fields_t* fields, epan_dissect_t* edt, FILE* fh)
+{
+    int level_of_indentation = 1;
+    write_wsml_data node_callback_data;
+    node_callback_data.level_of_indentation = level_of_indentation;
+    node_callback_data.fh = fh;
+    node_callback_data.data_sources = edt->pi.data_src;
+    node_callback_data.fields = fields;
+
+    ws_assert(edt);
+    ws_assert(fh);
+
+    const char* info_column_text = edt->pi.cinfo != NULL ? col_get_text(edt->pi.cinfo, COL_INFO) : NULL;
+    info_column_text = info_column_text != NULL ? info_column_text : "";
+
+    fprintf(fh, "\n<packet");
+    fprintf(fh, " number=\"%u\"", edt->pi.num);
+    fprintf(fh, " length=\"%u\"", edt->pi.fd->pkt_len);
+    fprintf(fh, " captured_length=\"%u\"", edt->pi.fd->cap_len);
+    fprintf(fh, " timestamp_seconds=\"%" PRId64 "\"", edt->pi.abs_ts.secs);
+    fprintf(fh, " timestamp_nanoseconds=\"%d\"", edt->pi.abs_ts.nsecs);
+    fprintf(fh, " info=\"");
+    print_escaped_xml(fh, info_column_text);
+    fprintf(fh, "\">");
+
+    // Write buffers
+    GSList* data_sources_item = edt->pi.data_src;
+    while (data_sources_item != NULL)
+    {
+        struct data_source* data_source = (struct data_source*)data_sources_item->data;
+        tvbuff_t* current_buffer = get_data_source_tvb(data_source);
+
+        fprintf(fh, "\n");
+        print_indent(level_of_indentation, fh);
+        fprintf(fh, "<buffer>");
+
+        guint buffer_length = tvb_captured_length(current_buffer);
+        for (guint j = 0; j < buffer_length; j++)
+        {
+            guint8 current_byte = tvb_get_guint8(current_buffer, j);
+            fprintf(fh, "%X", current_byte);
+        }
+        fprintf(fh, "</buffer>");
+
+        data_sources_item = data_sources_item->next;
+    }
+
+    // Write fields
+    proto_tree_children_foreach(edt->tree, proto_tree_write_node_wsml, &node_callback_data);
+
+    fprintf(fh, "\n</packet>");
+}
