+static gboolean
+write_wsml_packet(capture_file *cf, frame_data *fdata, wtap_rec *rec, Buffer *buf, void *argsp)
+{
+    write_packet_callback_args_t *args = (write_packet_callback_args_t *)argsp;
+
+    // Create the protocol tree, but don't fill in the column information.
+    epan_dissect_run(&args->edt, cf->cd_t, rec,
+            frame_tvbuff_new_buffer(&cf->provider, fdata, buf),
+            fdata, NULL);
+
+    // Write out the information in that tree.
+    write_wsml_proto_tree(NULL, &args->edt, args->fh);
+
+    epan_dissect_reset(&args->edt);
+
+    return !ferror(args->fh);
+}
+
+cf_print_status_t
+cf_write_wsml_packets(capture_file *cf, print_args_t *print_args)
+{
+    write_packet_callback_args_t callback_args;
+    FILE         *fh;
+    psp_return_t  ret;
+
+    fh = ws_fopen(print_args->file, "w");
+    if (fh == NULL)
+        return CF_PRINT_OPEN_ERROR; // attempt to open destination failed
+
+    write_wsml_preamble(fh, cf->filename);
+    if (ferror(fh)) {
+        fclose(fh);
+        return CF_PRINT_WRITE_ERROR;
+    }
+
+    callback_args.fh = fh;
+    callback_args.print_args = print_args;
+    epan_dissect_init(&callback_args.edt, cf->epan, TRUE, TRUE);
+
+    // Iterate through the list of packets, printing the packets we were told to print.
+    ret = process_specified_records(cf, &print_args->range, "Writing WSML",
+            "selected packets", TRUE,
+            write_wsml_packet, &callback_args, TRUE);
+
+    epan_dissect_cleanup(&callback_args.edt);
+
+    switch (ret) {
+
+        case PSP_FINISHED:
+            // Completed successfully.
+            break;
+
+        case PSP_STOPPED:
+            // Well, the user decided to abort the printing.
+            break;
+
+        case PSP_FAILED:
+            // Error while printing.
+            fclose(fh);
+            return CF_PRINT_WRITE_ERROR;
+    }
+
+    write_wsml_finale(fh);
+    if (ferror(fh)) {
+        fclose(fh);
+        return CF_PRINT_WRITE_ERROR;
+    }
+
+    // XXX - check for an error
+    fclose(fh);
+
+    return CF_PRINT_OK;
+}
